INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 4, 'theory', 'Квиз: журналы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 4, 0, 'Что решает, будет ли журнал journald переживать перезагрузку при Storage=auto?', '["Значение параметра SystemMaxUse", "Наличие установленного rsyslog", "Существование каталога /var/log/journal", "Объём оперативной памяти"]', 2, 'При auto журнал постоянный, только если каталог /var/log/journal существует, иначе записи лежат в /run/log/journal и пропадают при перезагрузке.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 4, 1, 'Что делает селектор «*.*;auth,authpriv.none» в строке правила rsyslog?', '["Выбирает только сообщения auth и authpriv", "Выбирает все сообщения, кроме категорий auth и authpriv", "Выбирает сообщения с приоритетом none", "Отключает всё правило"]', 1, 'Селекторы применяются слева направо: *.* выбирает всё, а auth,authpriv.none вычитает эти две категории.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 4, 2, 'Какая категория и какой приоритет в сообщении с числом PRI, равным 38?', '["user, debug", "mail, notice", "kern, err", "auth, info"]', 3, '38 = 4 × 8 + 6: категория 4 это auth, приоритет 6 это info.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 4, 3, 'Что даёт delaycompress вместе с compress?', '["Сжатие предыдущей копии откладывается до следующей ротации", "Файл сжимается до ротации", "Несжатые копии удаляются сразу", "Сжимаются только пустые файлы"]', 0, 'Самая свежая копия остаётся несжатой, пока программа может ещё писать в неё; сжимается она на следующем круге.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 4, 4, 'Что удаляется, когда журналу не хватает места из-за SystemMaxUse или SystemKeepFree?', '["Активный файл журнала", "Самые новые записи", "Только архивные файлы, начиная с самых старых", "Все файлы старше суток"]', 2, 'Журнал удаляет только архивные файлы, старые первыми; активный файл не трогают. Вручную то же делает journalctl --vacuum-size.');
